local KTool = CS.Engine.Lib.KTool
local BaseEffect = import('Game.Chapter.NewChapterEffect.BaseEffect')
local NewChapterConstants = import('Game.Chapter.NewChapterConstants')
local base = BaseEffect
local cs_coroutine = require "XLua.cs_coroutine"
local ResourceModule = CS.Engine.Modules.ResourceModule
local Yielders = CS.Engine.Lib.Yielders
local GameObject = CS.UnityEngine.GameObject

local ChapterChangeColorEffect = Class('ChapterChangeColorEffect',BaseEffect)

function ChapterChangeColorEffect:__init()
    self.isDel = false
    self.durationTime = 0
    self.isCanStart = false
end

function ChapterChangeColorEffect:__delete()
    self.isDel = false
    self.durationTime = 0
    self.isCanStart = false
end

function ChapterChangeColorEffect:Initialize(parameters)
    base.StartEffect(self, parameters)
    self.durationTime = parameters.durationTime
    local transientNum = string.split(parameters.transientNum,"_")
    if table.count(transientNum) > 0 then
        self.startNum = checkNumber(transientNum[1])
        self.endNum = checkNumber(transientNum[2])
        if checkNumber(self.startNum) > checkNumber(self.endNum) then
            self.isDel = true
        end
        self.isCanStart = true
    end
end

function ChapterChangeColorEffect:StartEffect(object)
    base.StartEffect(self, object)
    if not self.isCanStart then
        return
    end
    local character = object.transform:Find(NewChapterConstants.CharacterHairRoot)
    if isNull(character) then
        return
    end

    local childCount = character.childCount
    for i = 1, childCount do
        local go = character.transform:GetChild(i - 1)
        local name = go.name
        if string.contains(name,"_Blend") then
            local skinnedMeshRenderer = KTool.GetComponent(go.gameObject,typeof(CS.UnityEngine.SkinnedMeshRenderer))
            if not isNull(skinnedMeshRenderer) then
                local mat = skinnedMeshRenderer.material
                CfUtils.DoTween(self.durationTime,function(_value)
                    local value = _value
                    if self.isDel then
                        value = (1 - _value) * (self.startNum - self.endNum) + self.endNum
                    else
                        value = _value * (self.endNum - self.startNum) + self.startNum
                    end
                    mat:SetFloat("_HairBlend", value)
                end)
            end
        end
    end
end

function ChapterChangeColorEffect:IsFinish()
    base.IsFinish(self)
end

function ChapterChangeColorEffect:EndEffect(object)
    base.EndEffect(self, object)
end

function ChapterChangeColorEffect:RemoveEffect(object)
    base.RemoveEffect(self, object)
end

function ChapterChangeColorEffect:OnDestroy()
    self.controller = nil--luabehaviour 中CSharp对象
    self:Delete()
end

return ChapterChangeColorEffect